content.css:
/* ========================================================================== */
/* BFUSION Resource Heatmap — Layout & Chrome                                 */
/* ========================================================================== */
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-surface, #F8F9FB);
  position: relative;
  color: var(--bf-text, #242424);
  -webkit-font-smoothing: antialiased;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-rh {
  display: flex;
  flex-direction: column;
  padding-bottom: 22px;
  /* license badge clear-zone */
}
/* ── Header bar ─────────────────────────────────────────────────────────── */
.rh-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 18px 10px 18px;
  background: var(--bf-surface, #F8F9FB);
  position: relative;
}
.rh-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.rh-header__title {
  font-weight: 650;
  color: var(--bf-text, #111827);
  letter-spacing: -0.01em;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rh-header__subtitle {
  margin-top: 2px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rh-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: all 0.15s ease;
  font-family: inherit;
  padding: 0;
}
.rh-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
  outline: none;
}
.rh-header__info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.rh-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 14px;
  z-index: 30;
  width: 288px;
  max-width: calc(100% - 28px);
  background: var(--bf-surface, #F8F9FB);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 10px;
  box-shadow: 0 10px 28px rgba(16, 24, 40, 0.12);
  padding: 14px 16px;
  color: var(--bf-text, #242424);
  line-height: 1.5;
}
.rh-header__info-pop ul {
  margin: 6px 0 0 0;
  padding-left: 16px;
}
.rh-header__info-pop ul li {
  margin: 4px 0;
  color: var(--bf-muted, #667079);
}
.rh-info-pop__title {
  font-weight: 650;
  color: var(--bf-text, #111827);
  margin-bottom: 6px;
}
.rh-info-pop__desc {
  color: var(--bf-muted, #667079);
}
.rh-info-pop__howto {
  margin-top: 10px;
  font-weight: 600;
  font-size: 0.92em;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #9CA3AF;
}
.rh-diag {
  margin-top: 4px;
  font-size: 0.94em;
  font-variant-numeric: tabular-nums;
}
.rh-diag__row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 2px 0;
  border-bottom: 1px dotted var(--bf-rule, #E5E7EB);
}
.rh-diag__row:last-child {
  border-bottom: none;
}
.rh-diag__row span:first-child {
  color: #9CA3AF;
  white-space: nowrap;
}
.rh-diag__row span:last-child {
  color: var(--bf-text, #242424);
  text-align: right;
}
/* ── Toolbar: timeline slicer + what-if threshold ───────────────────────── */
.rh-controls {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 18px;
  padding: 8px 18px 10px 18px;
  background: var(--bf-surface, #F8F9FB);
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
}
.rh-controls__group {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}
.rh-controls__group--threshold {
  margin-left: auto;
}
.rh-controls__label {
  font-size: 9.5px;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #9CA3AF;
  white-space: nowrap;
}
.rh-controls__slider {
  flex: 0 1 180px;
  min-width: 84px;
  height: 4px;
  accent-color: var(--rh-insight-accent, #E8612A);
  cursor: pointer;
}
.rh-controls__readout {
  font-size: 11px;
  font-weight: 650;
  color: var(--bf-text, #111827);
  font-variant-numeric: tabular-nums;
  min-width: 34px;
}
/* ── Body row: chart + insight strip + insight panel ────────────────────── */
.rh-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: row;
  min-height: 0;
  overflow: hidden;
}
.rh-chart-col {
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
/* ── Data-limit / data-quality warning above the grid ──────────────────── */
/* Translucent amber over the theme surface, text in the theme ink, so it reads
   in light and dark alike. */
.rh-notice {
  margin: 8px 18px 0 18px;
  padding: 6px 10px;
  border-left: 3px solid #F59E0B;
  border-radius: 4px;
  background: rgba(245, 158, 11, 0.12);
  color: var(--bf-text, #242424);
  font-size: 11px;
  line-height: 1.4;
}
.rh-notice__line + .rh-notice__line {
  margin-top: 2px;
}
/* ── Legend chips (also band filters) ──────────────────────────────────── */
.rh-legend {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  padding: 10px 18px 6px 18px;
}
.rh-legend__title {
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #9CA3AF;
  margin-right: 5px;
}
.rh-legend__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface, #F8F9FB);
  color: var(--bf-muted, #667079);
  font-size: inherit;
  font-family: inherit;
  line-height: 1.6;
  cursor: pointer;
  transition: border-color 0.15s ease, color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}
.rh-legend__chip:hover {
  color: var(--bf-text, #111827);
  border-color: #9CA3AF;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.05);
}
.rh-legend__chip--active {
  /* Dark chip under white text: the band token stays dark in both themes. */
  border-color: var(--bf-band, #1F2A44);
  background: var(--bf-band, #1F2A44);
  color: #FFFFFF;
  font-weight: 600;
}
.rh-legend__chip--dim {
  opacity: 0.4;
}
.rh-legend__chip:focus-visible {
  outline: 2px solid var(--rh-insight-accent, #E8612A);
  outline-offset: 1px;
}
.rh-legend__swatch {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.06);
}
/* ── Scrollable heatmap area ───────────────────────────────────────────── */
.rh-chart-scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 2px 10px 10px 10px;
  scrollbar-width: thin;
}
.rh-chart-scroll::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}
.rh-chart-scroll::-webkit-scrollbar-thumb {
  background: var(--bf-rule, #E5E7EB);
  border-radius: 999px;
  border: 2px solid var(--bf-surface, #F8F9FB);
}
.rh-chart-scroll::-webkit-scrollbar-thumb:hover {
  background: var(--bf-rule, #E5E7EB);
}
.rh-chart-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.rh-cell rect {
  transition: filter 0.12s ease;
}
.rh-cell:hover rect {
  filter: brightness(0.95) drop-shadow(0 2px 6px rgba(16, 24, 40, 0.22));
}
.rh-collabel,
.rh-rowlabel {
  transition: fill 0.12s ease;
}
.rh-collabel:hover,
.rh-rowlabel:hover {
  fill: var(--rh-insight-accent, #E8612A);
}
/* ── Tooltip card (mirrors the Financial S-Curve) ──────────────────────── */
.rh-tooltip {
  position: absolute;
  z-index: 999;
  display: none;
  pointer-events: none;
  max-width: 260px;
  padding: 8px 12px;
  background: color-mix(in srgb, var(--bf-tile, #fff) 97%, transparent);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.12);
  font-family: inherit;
  font-size: 11px;
  line-height: 1.45;
  color: var(--bf-text, #242424);
}
.rh-tooltip__head {
  font-weight: 600;
  color: var(--bf-text, #111827);
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  padding-bottom: 3px;
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rh-tooltip__row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.rh-tooltip__k {
  color: var(--bf-muted, #667079);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}
.rh-tooltip__v {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.rh-tooltip__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex: 0 0 auto;
}
.rh-tooltip__note {
  border-top: 1px solid var(--bf-rule, #E5E7EB);
  padding-top: 3px;
  margin-top: 3px;
  color: #9CA3AF;
}
/* ========================================================================== */
/* Insight panel — collapsed strip + expanded panel                          */
/* ========================================================================== */
.rh-insight-strip {
  flex: 0 0 26px;
  width: 26px;
  background: var(--bf-surface-alt, #F4F5F7);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-muted, #667079);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.rh-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
  line-height: 1;
}
.rh-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-weight: 650;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  font-size: 9px;
}
.rh-insight-strip:hover,
.rh-insight-strip:focus {
  background: var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  outline: none;
}
.rh-insight-strip:hover .rh-insight-strip__label,
.rh-insight-strip:focus .rh-insight-strip__label {
  color: var(--bf-muted, #667079);
}
.rh-insight-panel {
  flex: 0 0 262px;
  max-width: 330px;
  background: var(--bf-surface, #F8F9FB);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  display: flex;
  flex-direction: column;
  padding: 14px 14px 16px 14px;
  overflow-y: auto;
  font-size: var(--rh-insight-font, 11px);
  color: var(--bf-text, #242424);
  gap: 12px;
  scrollbar-width: thin;
}
.rh-insight-panel::-webkit-scrollbar {
  width: 8px;
}
.rh-insight-panel::-webkit-scrollbar-thumb {
  background: var(--bf-rule, #E5E7EB);
  border-radius: 999px;
  border: 2px solid var(--bf-surface, #F8F9FB);
}
.rh-insight-panel::-webkit-scrollbar-track {
  background: transparent;
}
.rh-insight__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
}
.rh-insight__title {
  font-size: var(--rh-insight-header-font, 12px);
  font-weight: 650;
  color: var(--bf-text, #111827);
  letter-spacing: -0.01em;
  position: relative;
  padding-left: 9px;
}
.rh-insight__title:before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.18em;
  bottom: 0.18em;
  width: 3px;
  border-radius: 999px;
  background: var(--rh-insight-accent, #E8612A);
}
.rh-insight__subtitle {
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  color: #9CA3AF;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 55%;
}
.rh-insight__scope-reset {
  align-self: flex-start;
  border: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-muted, #667079);
  background: var(--bf-surface, #F8F9FB);
  border-radius: 999px;
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  font-family: inherit;
  padding: 3px 10px;
  cursor: pointer;
  transition: all 0.15s ease;
}
.rh-insight__scope-reset:hover {
  background: var(--bf-band, #1F2A44);
  border-color: var(--bf-band, #1F2A44);
  color: #FFFFFF;
}
.rh-insight__scope-reset:focus-visible {
  outline: 2px solid var(--rh-insight-accent, #E8612A);
  outline-offset: 1px;
}
.rh-insight__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
}
.rh-kpi {
  background: var(--bf-surface, #F8F9FB);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 8px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  position: relative;
  overflow: hidden;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}
.rh-kpi:before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--rh-kpi-color, #E8612A);
}
.rh-kpi--clickable {
  cursor: pointer;
}
.rh-kpi--clickable:hover {
  border-color: #9CA3AF;
  box-shadow: 0 4px 12px rgba(16, 24, 40, 0.08);
  transform: translateY(-1px);
}
.rh-kpi--clickable:focus-visible {
  outline: 2px solid var(--rh-insight-accent, #E8612A);
  outline-offset: 1px;
}
.rh-kpi--active {
  border-color: var(--rh-insight-accent, #E8612A);
  box-shadow: 0 0 0 1px var(--rh-insight-accent, #E8612A) inset;
}
.rh-kpi__value {
  font-size: calc(var(--rh-insight-font, 11px) + 4px);
  font-weight: 650;
  color: var(--rh-kpi-color, var(--bf-text, #111827));
  line-height: 1.15;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rh-kpi__label {
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  color: #9CA3AF;
}
.rh-insight__section {
  background: var(--bf-surface, #F8F9FB);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 8px;
  padding: 10px 11px 11px 11px;
}
.rh-insight__section-title {
  font-weight: 650;
  color: #9CA3AF;
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 8px;
}
/* Stacked distribution health bar */
.rh-insight__health {
  display: flex;
  height: 8px;
  border-radius: 999px;
  overflow: hidden;
  background: #F1F2F4;
  gap: 1px;
}
.rh-insight__health-seg {
  flex-basis: 0;
  min-width: 3px;
}
.rh-insight__health-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin-top: 8px;
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
}
.rh-insight__health-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.rh-insight__health-legend i {
  width: 7px;
  height: 7px;
  border-radius: 2px;
  display: inline-block;
}
/* Focused-resource trend chart */
.rh-trendchart {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.rh-trendchart__axis {
  display: flex;
  justify-content: space-between;
  margin-top: 2px;
  font-size: calc(var(--rh-insight-font, 11px) - 2px);
  color: #9CA3AF;
}
.rh-trendchart__facts {
  display: flex;
  flex-wrap: wrap;
  gap: 3px 10px;
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px solid #F1F2F4;
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
}
.rh-trendchart__facts strong {
  color: var(--bf-text, #111827);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}
.rh-insight__smart {
  margin: 0;
  padding-left: 15px;
}
.rh-insight__smart li {
  margin: 6px 0;
  line-height: 1.5;
  color: var(--bf-text, #242424);
}
.rh-insight__smart li::marker {
  color: var(--bf-rule, #E5E7EB);
}
.rh-insight__smart strong {
  font-weight: 650;
  color: var(--bf-text, #111827);
}
/* Clickable resource reference inside a smart insight */
.rh-insight__ref {
  font-weight: 650;
  color: var(--bf-text, #111827);
  cursor: pointer;
  border-bottom: 1px dashed #9CA3AF;
  transition: color 0.12s ease, border-color 0.12s ease;
}
.rh-insight__ref:hover {
  color: var(--rh-insight-accent, #E8612A);
  border-bottom-color: var(--rh-insight-accent, #E8612A);
}
.rh-insight__ref--active {
  color: var(--rh-insight-accent, #E8612A);
  border-bottom-style: solid;
  border-bottom-color: var(--rh-insight-accent, #E8612A);
}
.rh-insight__ref:focus-visible {
  outline: 2px solid var(--rh-insight-accent, #E8612A);
  outline-offset: 2px;
  border-radius: 2px;
}
.rh-insight__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.rh-insight__list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 6px;
  margin-bottom: 3px;
  background: var(--bf-surface, #F8F9FB);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.13s ease, border-color 0.13s ease, transform 0.13s ease;
}
.rh-insight__list li:last-child {
  margin-bottom: 0;
}
.rh-insight__list li:hover {
  background: var(--bf-surface, #F8F9FB);
  border-color: var(--bf-rule, #E5E7EB);
  transform: translateX(1px);
}
.rh-insight__list li:focus-visible {
  outline: 2px solid var(--rh-insight-accent, #E8612A);
  outline-offset: 1px;
}
.rh-insight__list-item--active {
  background: var(--bf-surface, #F8F9FB);
  border-color: var(--rh-insight-accent, #E8612A) !important;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.05);
}
.rh-insight__list-item--active .rh-insight__name {
  font-weight: 650;
  color: var(--bf-text, #111827);
}
.rh-insight__dot {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: 50%;
}
.rh-insight__name {
  flex: 1 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--bf-text, #242424);
}
.rh-insight__val {
  flex: 0 0 auto;
  font-weight: 650;
  color: var(--bf-text, #111827);
  font-variant-numeric: tabular-nums;
}
/* Operational call banner */
.rh-insight__call {
  margin-top: auto;
  border-radius: 8px;
  padding: 10px 11px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface, #F8F9FB);
}
.rh-insight__call--warn {
  border-color: rgba(239, 68, 68, 0.28);
  background: rgba(239, 68, 68, 0.045);
}
.rh-insight__call--warn .rh-insight__call-value {
  color: #DC2626;
}
.rh-insight__call--ok {
  border-color: rgba(34, 197, 94, 0.28);
  background: rgba(34, 197, 94, 0.045);
}
.rh-insight__call--ok .rh-insight__call-value {
  color: #15803D;
}
.rh-insight__call-label {
  font-size: calc(var(--rh-insight-font, 11px) - 2px);
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #9CA3AF;
  margin-bottom: 3px;
}
.rh-insight__call-value {
  font-weight: 650;
}
/* Insight panel visibility states */
.rh-body--insight-collapsed .rh-insight-panel {
  display: none;
}
.rh-body--insight-hidden .rh-insight-panel,
.rh-body--insight-hidden .rh-insight-strip {
  display: none;
}
/* ========================================================================== */
/* Responsive width classes                                                   */
/* ========================================================================== */
.rh-medium .rh-insight-panel {
  flex-basis: 228px;
}
.rh-medium .rh-controls__slider {
  flex-basis: 130px;
}
.rh-medium .rh-controls {
  gap: 6px 12px;
}
.rh-narrow .rh-insight-panel {
  position: absolute;
  right: 26px;
  top: 0;
  bottom: 0;
  width: 244px;
  z-index: 25;
  box-shadow: 0 10px 28px rgba(16, 24, 40, 0.12);
}
.rh-narrow .rh-header {
  padding: 10px 14px 8px 14px;
}
.rh-narrow .rh-header__title {
  font-size: 12px !important;
}
.rh-narrow .rh-controls {
  padding: 7px 14px 8px 14px;
  gap: 6px 10px;
}
.rh-narrow .rh-controls__group--threshold {
  margin-left: 0;
}
.rh-narrow .rh-controls__slider {
  flex-basis: 92px;
}
.rh-narrow .rh-legend {
  padding: 8px 14px 4px 14px;
}
/* ========================================================================== */
/* Responsive Landing Page Framework                                         */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: var(--bf-muted, #667079);
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
